<div class="main-content"><?php require APP_ROOT.'/app/views/components/navbar.php';?><div class="content-wrapper"><div class="d-flex justify-content-between mb-3"><div><h5 class="mb-1">Occupancy Report</h5><p class="text-muted mb-0">Room capacity and current allocation.</p></div><a class="btn btn-outline-primary btn-sm" href="<?=url('views/houseparent/rooms/index.php')?>">Open rooms</a></div><div class="row g-3 mb-3"><?php foreach(['rooms'=>'Rooms','capacity'=>'Capacity','occupied'=>'Occupied','vacant'=>'Vacant'] as $key=>$label):?><div class="col-md-3"><div class="card stat-card p-3"><small class="text-muted"><?=e($label)?></small><strong class="fs-2"><?=e((string)($stats[$key]??0))?></strong></div></div><?php endforeach;?></div><div class="card stat-card p-3"><table class="table table-hover"><thead><tr><th>Room</th><th>Capacity</th><th>Occupied</th><th>Vacant</th><th>Status</th></tr></thead><tbody><?php foreach($rooms as $room):$capacity=(int)($room['capacity']??0);$occupied=(int)($room['occupied']??$room['occupancy']??0);?><tr><td><?=e($room['roomNumber']??'-')?></td><td><?=e((string)$capacity)?></td><td><?=e((string)$occupied)?></td><td><?=e((string)max(0,$capacity-$occupied))?></td><td><?=e($room['status']??'unknown')?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require APP_ROOT.'/app/views/components/footer.php';?>